mapper.select:
select a.*
from collection_base_info a,contract_base_info b

    a.contract_id = b.id
    and a.client_id = #{dto.clientId}
    and a.write_off_status = #{dto.status}
    and a.cash_flow_item = #{dto.cashFlowItem}
    and a.contract_code LIKE concat('%', #{dto.contractCode},'%')
    and a.plan_collection_amount  >=  #{dto.amountFrom}
    and a.plan_collection_amount  <=  #{dto.amountTo}
    and a.collection_date  >=  #{dto.collectionDateFrom}
    and a.collection_date  <=  #{dto.collectionDateTo}
    and a.plan_collection_date  >=  #{dto.planCollectionDateFrom}
    and a.plan_collection_date  <=  #{dto.planCollectionDateTo}
    

order by a.contract_code,a.plan_collection_date,a.code asc

select receipt_id, max(plan_collection_date) plan_collection_date from collection_base_info where cash_flow_item = 'RENT' and receipt_id in
#{item}
group by receipt_id

select contract_id contractId, max(plan_collection_date) settleDate FROM collection_base_info where cash_flow_item = 'RENT' and contract_id in
#{item}
GROUP BY contract_id

SELECT a.receipt_id receipt_id, max( a.plan_collection_date ) plan_collection_date, a.receipt_remaining_principal receipt_remaining_principal FROM ( SELECT c.receipt_id receipt_id, c.plan_collection_date plan_collection_date, ( SELECT remaining_principal FROM contract_rent_actual WHERE id = c.rent_actual_id ) receipt_remaining_principal, c.rent_actual_id rentActualId FROM collection_base_info c WHERE c.cash_flow_item = 'RENT' AND c.receipt_id IS NOT NULL and #{planDate} >= c.plan_collection_date and receipt_id in
#{item}
ORDER BY receipt_id, plan_collection_date DESC ) a GROUP BY a.receipt_id

select a.collection_id, a.write_off_status, CASE a.write_off_status WHEN 'UNCOLLECTION' THEN 10 WHEN 'TO_BE_WRITE_OFF' THEN 40 WHEN 'PORTION_WRITTEN_OFF' THEN 20 WHEN 'WRITE_OFF_COMPLETED' THEN 30 ELSE 50 END as sort, a.client_id, a.contract_code, a.phase, a.cash_flow_item, a.biz_dept_id, a.plan_collection_date, a.plan_collection_amount, a.principal, a.interest, a.collection_amount, a.collection_date, a.code, a.proj_name, biz_type, lease_type, retreat_lock from ( SELECT c.id AS collection_id, 'TO_BE_WRITE_OFF' write_off_status, c.client_id, c.contract_code, c.phase, c.cash_flow_item, b.biz_dept_id, c.plan_collection_date, c.plan_collection_amount, c.principal, c.interest, c.collection_amount, c.collection_date, c.CODE, b.proj_name, b.biz_type, b.lease_type, c.retreat_lock FROM collection_base_info c LEFT JOIN contract_base_info b ON c.contract_id = b.id WHERE c.write_off_status IN ( 'UNCOLLECTION', 'TO_BE_WRITE_OFF' ) and c.plan_collection_date > now() union ALL SELECT c.id AS collection_id, 'UNCOLLECTION' write_off_status, c.client_id, c.contract_code, c.phase, c.cash_flow_item, b.biz_dept_id, c.plan_collection_date, c.plan_collection_amount, c.principal, c.interest, c.collection_amount, c.collection_date, c.CODE, b.proj_name, b.biz_type, b.lease_type, c.retreat_lock FROM collection_base_info c LEFT JOIN contract_base_info b ON c.contract_id = b.id WHERE c.write_off_status IN ( 'UNCOLLECTION', 'TO_BE_WRITE_OFF' ) and now() >= c.plan_collection_date UNION ALL SELECT c.id AS collection_id, c.write_off_status, c.client_id, c.contract_code, c.phase, c.cash_flow_item, b.biz_dept_id, c.plan_collection_date, c.plan_collection_amount, c.principal, c.interest, c.collection_amount, c.collection_date, c.CODE, b.proj_name, b.biz_type, b.lease_type, c.retreat_lock FROM collection_base_info c LEFT JOIN contract_base_info b ON c.contract_id = b.id WHERE c.write_off_status in ('PORTION_WRITTEN_OFF', 'WRITE_OFF_COMPLETED') ) a
and a.plan_collection_date >= #{dto.planCollectionDateFrom} and a.plan_collection_date <= #{dto.planCollectionDateTo} and a.client_id = #{dto.clientId} and a.cash_flow_item in
#{item}
and a.contract_code LIKE concat('%', #{dto.contractCode},'%') and a.biz_dept_id = #{dto.bizDeptId} and a.contract_id = #{dto.contractId} and a.write_off_status in
#{item}
ORDER BY sort asc, plan_collection_date desc

SELECT c1.client_name AS clientName, c1.id AS clientId, proj_review.proj_name AS projName, contract.contract_code AS contractCode, collection.phase AS phase, collection.contract_id AS contractId, ROUND((IFNULL(collection.plan_collection_amount, 0) - IFNULL(collection.collection_amount, 0)) / 100000000, 2) AS overdueAmount, ROUND((IFNULL(collection.penalty_interest, 0) - IFNULL(collection.collection_amount, 0)) / 100000000, 2) AS penaltyInterestAmount, contract.biz_type AS bizType, c2.client_name AS tenantry, contract.biz_dept_id AS bizDeptId, contract.proj_sponsor_user_id AS projSponsorUserId, contract.proj_cosponsor_user_ids AS projCosponsorUserIds, ROUND(IFNULL(collection.penalty_interest_deduction_amount, 0) / 100000000, 2) AS penaltyInterestReductionAmount FROM collection_base_info collection LEFT JOIN contract_base_info contract ON contract.id = collection.contract_id LEFT JOIN proj_review_base_info proj_review ON proj_review.id = contract.proj_review_id LEFT JOIN contract_tenantry tenantry ON tenantry.contract_id = contract.id LEFT JOIN contract_guarantor guarantor ON guarantor.contract_id = contract.id LEFT JOIN client c1 ON collection.client_id = c1.id LEFT JOIN client c2 ON tenantry.lessee_id = c2.id WHERE (IFNULL(plan_collection_amount, 0) - IFNULL(collection_amount, 0)) > 0 AND collection.cash_flow_item = 'RENT' AND collection.plan_collection_date < CURRENT_DATE AND collection.phase > 0 AND collection.client_id IN
#{clientId}
AND collection.client_id LIKE CONCAT('%', #{query.clientId}, '%')
AND proj_review.proj_name LIKE CONCAT('%', #{query.projName}, '%')
AND collection.contract_code LIKE CONCAT('%', #{query.contractCode}, '%')
AND contract.biz_dept_id = #{query.bizDeptId}
AND contract.proj_sponsor_user_id = #{query.projSponsorUserId}
AND collection.plan_collection_date >= #{query.beginTime}
AND collection.plan_collection_date <= #{query.endTime}
GROUP BY collection.code

select p.* from
(select min(plan_collection_date) as plan_collection_date, contract_id from collection_base_info
where cash_flow_item = 'RENT' and write_off_status != 'WRITE_OFF_COMPLETED'
group by contract_id ) as a left join collection_base_info p on a.contract_id = p.contract_id and a.plan_collection_date =
p.plan_collection_date
inner join contract_base_info cbi on cbi.id = p.contract_id

    AND p.client_id = #{dto.clientId}
    
        and
        (cbi.biz_dept_id IN
        
            #{item}
        
        OR cbi.proj_sponsor_user_id = #{dto.currentUserId}
        OR JSON_CONTAINS(cbi.proj_cosponsor_user_ids, CONVERT (#{dto.currentUserId}, CHAR))
        )

SELECT b.* FROM ( SELECT c.receipt_id receipt_id, min( c.plan_collection_date ) plan_collection_date FROM collection_base_info c WHERE c.cash_flow_item = 'RENT' AND c.receipt_id IS NOT NULL and c.plan_collection_date >= #{planDate} and receipt_id in
#{item}
group by receipt_id ) a left join collection_base_info b on a.receipt_id = b.receipt_id and a.plan_collection_date = b.plan_collection_date GROUP BY a.receipt_id
